```python
def set_tick_params(self, which='major', reset=False, **kw):
    """
    Set appearance parameters for ticks, ticklabels, and gridlines.

    For documentation of keyword arguments, see
    :meth:`matplotlib.axes.Axes.tick_params`.
    """
    cbook._check_in_list(['major', 'minor', 'both'], which=which)
    kwtrans = self._translate_tick_kw(kw)

    # the kwargs are stored in self._major/minor_tick_kw so that any
    # future new ticks will automatically get them
    if reset:
        if which in ['major', 'both']:
            self._major_tick_kw.clear()
            self._major_tick_kw.update(kwtrans)
        if which in ['minor', 'both']:
            self._minor_tick_kw.clear()
            self._minor_tick_kw.update(kwtrans)
        self.reset_ticks()
    else:
        if which in ['major', 'both']:
            self._major_tick_kw.update(kwtrans)
            for tick in self.majorTicks:
                tick._apply_params(**kwtrans)
        if which in ['minor', 'both']:
            self._minor_tick_kw.update(kwtrans)
            for tick in self.minorTicks:
                tick._apply_params(**kwtrans)
        # special-case label color to also apply to the offset text
        if 'labelcolor' in kwtrans:
            self.offsetText.set_color(kwtrans['labelcolor'])

        # New condition to hide offset text if no major ticks are present
        if which == 'major' and not self._major_tick_kw.get('label1On', True) and not self._major_tick_kw.get('label2On', True):
            self.offsetText.set_visible(False)

    self.stale = True
